#!/bin/bash
# usage: flying_run.sh <name> "<design brief>"   (runs Codex headless, writes flying_src/<name>_flying.png)
D=/Users/sina/Developer/Pause/.claude/worktrees/agent-a10fa502a0c8b52e0/Pause/Assets/Art/Enemies/src~/tide_enemies
N="$1"; BRIEF="$2"
PROMPT="You are repainting ONE game enemy sprite (attached image: ${N}_in.png, transparent background, top-down view facing down). Use your image generation tool to produce a NEW image of the SAME enemy, same pose, same camera, same overall silhouette and design, same pixel-art style (crisp hard pixel edges, dense 4-6 tone ramps, rivets, scratches), on a genuinely transparent square background with generous margin, the sprite centred and filling about the same area. Two changes only. (1) RECOLOUR: the original is one teal/green-grey palette. Repaint with SEVERAL distinct, saturated accent colours so hull, trim, glowing parts and weapon/engine each have their own hue: tangerine orange #FF8A1F, sun yellow #FFD21F, electric blue #2D9CFF, violet #8A4DFF, bright white, plus a little deep navy/gunmetal for shading. Keep luminous mint/teal only for small lights. FORBIDDEN colours: pink, magenta, red, lime green, muddy brown-grey. NO outline of any kind: no pale rim, no white border, no glow halo around the sprite; edges are just the painted body against transparency. (2) FLYING: this is an AIRBORNE machine in the sky, never a swimmer or ground creature. ${BRIEF} Remove anything that reads as water, dripping, seaweed, tide pools, mud or seabed. Output exactly one sprite image. Save the final PNG (RGBA, transparent background) to ${D}/flying_src/${N}_flying.png (copy it from the generated images folder if needed) and reply with just the path."
cd "$D/flying_src"
printf "%s" "$PROMPT" | ~/.local/bin/codex exec -s workspace-write -C "$D/flying_src" -i "$D/flying_src/${N}_in.png" -
